package com.danil.blackswordsman;
/** Closed 3D caps, stalks, gills, pores, leaves and fronds; two baked levels of detail. */
public final class FloraGeometry {
 public static ToyGeometry.Data build(int id,boolean detail){ToyGeometry.Builder b=new ToyGeometry.Builder(detail);b.detailScale=2;float[] cream={.65f,.59f,.43f};if(id<32){float[] c=FloraCatalog.color(id);int[] shapes={0,1,2,7,0,5,6,3,4,8,7,6,4,0,1,9,7,2,3,5,3,0,8,4,0,1,2,3,4,5,6,7};int shape=shapes[id];float h=.42f+(id%4)*.06f;b.cylinder(0,h*.5f,0,.065f,h*.5f,.065f,.8f,cream);if(shape==0||shape==2||shape==5){b.sphere(0,h,0,.43f,.18f,.43f,c);b.sphere(0,h-.06f,0,.37f,.035f,.37f,cream);if(detail)for(int i=0;i<14;i++){float a=i*2.39996f,r=.09f+(i%4)*.07f;b.sphere((float)Math.cos(a)*r,h+.18f*(float)Math.sqrt(Math.max(0,1-r*r/(.43f*.43f)))+.004f, (float)Math.sin(a)*r,.025f,.012f,.028f,shape==2?new float[]{.9f,.85f,.73f}:c);}}else if(shape==1||shape==6){b.cylinder(0,h,0,.12f,.17f,.12f,3,c);b.torus(0,h+.17f,0,.34f,.06f,c);b.sphere(0,h+.05f,0,.2f,.04f,.2f,cream);}else if(shape==3){for(int i=0;i<7;i++){float a=i*.9f,rr=.08f+i*.035f;b.rot(i*3,0,i*6-18).cylinder((float)Math.sin(a)*rr,h*.85f,(float)Math.cos(a)*rr,.045f,.22f+(i%3)*.05f,.045f,.6f,c);b.sphere((float)Math.sin(a)*rr,h*1.5f,(float)Math.cos(a)*rr,.055f,.065f,.055f,c);}}else if(shape==4){b.sphere(0,h*.6f,0,.35f,.32f,.35f,c);if(detail)for(int i=0;i<10;i++){float a=i*.628f;b.sphere((float)Math.sin(a)*.3f,h*.7f,(float)Math.cos(a)*.3f,.032f,.045f,.032f,cream);}}else if(shape==8){b.sphere(0,h+.13f,0,.22f,.34f,.22f,c);if(detail)for(int j=0;j<5;j++)for(int i=0;i<8;i++){float a=i*.7854f+j*.18f;b.sphere((float)Math.sin(a)*.19f,h-.06f+j*.08f,(float)Math.cos(a)*.19f,.038f,.050f,.022f,new float[]{c[0]*.45f,c[1]*.45f,c[2]*.45f});}}else if(shape==9){b.sphere(0,.24f,0,.20f,.22f,.20f,c);for(int i=0;i<6;i++){float a=i*60;b.rot(0,a,65).cylinder((float)Math.sin(a*.01745f)*.25f,.12f,(float)Math.cos(a*.01745f)*.25f,.10f,.23f,.06f,0,c);}}else{for(int i=0;i<3;i++)b.sphere(i*.13f-.13f,h+i*.15f,0,.3f,.07f,.23f,c);}
 if(detail&&(shape==0||shape==2||shape==5))for(int i=0;i<16;i++){float a=i*22.5f;b.rot(0,a,0).box(0,h-.145f,0,.006f,.007f,.27f,cream);}if(id>=24){b.torus(0,.04f,0,.38f,.035f,c);for(int i=0;i<4;i++){float a=i*1.57f;b.sphere((float)Math.sin(a)*.23f,h+.24f,(float)Math.cos(a)*.23f,.035f,.035f,.035f,new float[]{.8f,.95f,.85f});}}
 }else{plant(b,id-32,detail);}
 return b.finish();}
 private static void plant(ToyGeometry.Builder b,int k,boolean detailed){float[] green={.10f+(k%3)*.03f,.27f+(k%4)*.03f,.10f},light={.24f,.43f,.17f},brown={.39f,.28f,.11f},purple={.59f,.20f,.60f};int leaves=detailed?8:4;
 if(k==0){b.detailScale=1;for(int frond=0;frond<5;frond++){float a=frond*1.2566f,s=(float)Math.sin(a),c=(float)Math.cos(a);for(int j=1;j<=(detailed?6:3);j++){float t=j/(detailed?6f:3f),r=t*.64f,y=(float)Math.sin(t*2.6f)*.35f;b.rot(0,a*57.3f,0).cylinder(s*r,y,c*r,.012f,.08f,.012f,.8f,green);for(int side=-1;side<=1;side+=2)b.rot(18,a*57.3f+side*36,0).sphere(s*r+c*side*.07f,y,c*r-s*side*.07f,.035f,.012f,.17f*(1-t*.55f),light);}}return;}
 if(k==1||k==2||k==3||k==13){for(int i=0;i<leaves;i++){float a=i*2.4f,x=(float)Math.sin(a)*.23f,z=(float)Math.cos(a)*.23f,h=.4f+(i%3)*.15f;float[] col=k==13?brown:green;b.rot(0,a*57.3f,8).cylinder(x,h,z,.014f,h,.014f,.3f,col);if(k==2)b.sphere(x,h*1.85f,z,.045f,.17f,.045f,brown);if(k==3)for(int j=1;j<5;j++){b.torus(x,j*h*.35f,z,.04f,.008f,light);}if(k==13)b.rot(0,a*57.3f,20).cylinder(x,h*1.7f,z,.065f,.20f,.018f,.1f,brown);}return;}
 if(k==4){for(int j=0;j<4;j++){float a=j*1.57f,x=(float)Math.sin(a)*.28f,z=(float)Math.cos(a)*.28f;b.cylinder(x,.15f,z,.01f,.15f,.01f,1,green);for(int i=0;i<3;i++){float ang=i*2.094f;b.sphere(x+(float)Math.sin(ang)*.10f,.30f,z+(float)Math.cos(ang)*.10f,.10f,.012f,.10f,light);}}b.sphere(0,.38f,0,.065f,.065f,.065f,purple);return;}
 if(k==7){for(int i=0;i<leaves;i++){float a=i*360f/leaves; b.rot(48,a,0).cylinder((float)Math.sin(a*.01745f)*.18f,.25f,(float)Math.cos(a*.01745f)*.18f,.075f,.33f,.035f,.05f,green);}return;}
 if(k==14){b.detailScale=1;for(int i=0;i<(detailed?18:8);i++){float a=i*2.39996f,r=.12f+(i%4)*.11f;b.sphere((float)Math.sin(a)*r,.045f,(float)Math.cos(a)*r,.12f,.065f,.12f,light);if(i%3==0)b.cylinder((float)Math.sin(a)*r,.14f,(float)Math.cos(a)*r,.008f,.10f,.008f,1,new float[]{.10f,.76f,.65f});}return;}
 if(k==15){b.cylinder(0,.43f,0,.075f,.43f,.075f,.8f,green);for(int side=-1;side<=1;side+=2){b.rot(0,0,side*65).cylinder(side*.18f,.46f,0,.045f,.22f,.045f,1,green);b.sphere(side*.33f,.70f,0,.17f,.29f,.075f,light);}b.sphere(0,.9f,0,.18f,.27f,.085f,light);return;}
 if(k==8||k==12){for(int i=0;i<(k==12?5:8);i++){float a=i*2.39996f,r=.14f+(i%3)*.14f;b.rot(0,a*57.3f,0).sphere((float)Math.sin(a)*r,.05f+i*.008f,(float)Math.cos(a)*r,k==12?.23f:.13f,.014f,k==12?.22f:.15f,green);}return;}
 if(k==6){b.detailScale=1;for(int branch=0;branch<5;branch++){float a=branch*1.25f,x=(float)Math.sin(a)*.15f,z=(float)Math.cos(a)*.15f;b.cylinder(x,.35f,z,.015f,.35f,.015f,.5f,brown);for(int j=0;j<5;j++)b.sphere(x,.32f+j*.085f,z,.075f,.045f,.07f,purple);}return;}
 b.cylinder(0,.42f,0,.022f,.42f,.022f,.6f,green);for(int i=0;i<(k==9?4:leaves);i++){float a=i*137.5f,h=.13f+i*.055f,r=.15f+(i%3)*.055f;b.rot(18,a,15).sphere((float)Math.sin(a*.01745f)*r,h,(float)Math.cos(a*.01745f)*r,k==9?.26f:.10f,.021f,k==9?.36f:.20f,green);if(k==5&&detailed)b.rot(0,a,60).cylinder((float)Math.sin(a*.01745f)*r*2,h,(float)Math.cos(a*.01745f)*r*2,.012f,.10f,.012f,0,brown);}
 if(k==5||k==10){for(int i=0;i<8;i++){float a=i*.785f;b.rot(0,a*57.3f,15).sphere((float)Math.sin(a)*.08f,.84f,(float)Math.cos(a)*.08f,k==5?.045f:.10f,.028f,k==5?.06f:.18f,k==10?new float[]{.36f,.7f,.85f}:purple);}b.sphere(0,.86f,0,.045f,.025f,.045f,new float[]{.89f,.75f,.21f});}}
 private FloraGeometry(){}
}
